entries[47046] = { ["name"] = "Alchemistenstein des Wächters", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAlchemistenstein , Urluft (6), Nethervortex (2)\nVerkäufer:\nEldara Dämmerflucht\nZone:\nInsel von Quel'Danas\nOffensive der Zerschmetterten Sonne - Ehrfürchtig\nKosten:\n25\n\nAlchemistenstein des Wächters\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+ 7 Ausweichen\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[47048] = { ["name"] = "Alchemistenstein des Zauberers", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAlchemistenstein , Urfeuer (6), Nethervortex (2)\nVerkäufer:\nEldara Dämmerflucht\nZone:\nInsel von Quel'Danas\nOffensive der Zerschmetterten Sonne - Ehrfürchtig\nKosten:\n25\n\nAlchemistenstein des Zauberers\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+5 Intelligenz\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[47049] = { ["name"] = "Alchemistenstein des Erlösers", ["text"] = "Wirken in 3 sek.\nReagenzien:\nAlchemistenstein , Urleben (6), Nethervortex (2)\nVerkäufer:\nEldara Dämmerflucht\nZone:\nInsel von Quel'Danas\nOffensive der Zerschmetterten Sonne - Ehrfürchtig\nKosten:\n25\n\nAlchemistenstein des Erlösers\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+5 Intelligenz\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[47050] = { ["name"] = "Alchemistenstein des Assassinen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nAlchemistenstein , Urschatten (6), Nethervortex (2)\nVerkäufer:\nEldara Dämmerflucht\nZone:\nInsel von Quel'Danas\nOffensive der Zerschmetterten Sonne - Ehrfürchtig\nKosten:\n25\n\nAlchemistenstein des Assassinen\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)Schmuck\n+4 [Beweglichkeit oder Stärke] Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Scherbenwelt\n(50)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
