entries[48286] = { ["name"] = "Schrecklicher Hieb", ["text"] = "Nahkampfreichweite\nSofort\nEin hinterhältiger Angriff, der das Ziel stark bluten lässt, bis es vollständig geheilt wird. Fügt bis zur vollständigen Heilung alle 2 Sek. 2 Schaden zu." }
entries[48287] = { ["name"] = "Kraftvoller Biss", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht 100% des normalen Schadens und verringert die Rüstung des Gegners 5 Sek. lang um 20%." }
entries[48288] = { ["name"] = "Kolbenzerkrachen", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nFügt einem Feind und seinem nächsten Verbündeten 110% des normalen Nahkampfschadens zu und betäubt sie 2 Sek. lang." }
entries[48290] = { ["name"] = "Reitgerte des Scharlachroten Ansturms", ["text"] = "5 Meter Reichweite\nSofort\nSitzt auf das Schlachtross des Ansturms auf, sobald sein Reiter tot ist." }
entries[48291] = { ["name"] = "Eitrige Fäulnis", ["text"] = "Nahkampfreichweite\nSofort\nBelegt das Ziel mit 'Eitrige Fäulnis', verursacht alle 3 Sek. 420 Naturschaden und verringert seine erhaltene Heilung um 25%. Hält 9 Sek. lang an." }
entries[48292] = { ["name"] = "Dunkler Streich", ["text"] = "Nahkampfreichweite\nSofort\nSchlägt das Ziel mit Dunkelheit, verursacht Schaden in Höhe von 50% der aktuellen Gesundheit des Ziels." }
