entries[48319] = { ["name"] = "Alptraum", ["text"] = "1665 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 15 sek.)\nGreift den Geist des Ziels an und verursacht einen verstörenden Alptraum, der bei allen Feinden im Umkreis von 10 Metern um das Ziel (9.5% der Zaubermacht) Schattenschaden verursacht. Hält 15 Sek. lang an." }
